namespace {
bool destination_point_equal(const PointI& a,const PointI& b){return a.x==b.x&&a.y==b.y;}
bool original_destination_equal(const TravelDestination& a,const TravelDestination& b){if(a.index()!=b.index())return false;if(const auto* id=std::get_if<StableId>(&a))return *id==std::get<StableId>(b);return destination_point_equal(std::get<PointI>(a),std::get<PointI>(b));}
void registration(const ActionTimeRegistration& r){const auto actual=movement_action_time_registration(r.profile_version);if((r.profile_version!=4&&r.profile_version!=5)||r.action_kind!=actual.action_kind||r.owner_domain!=actual.owner_domain||r.profile_id!=actual.profile_id||r.profile_version!=actual.profile_version||r.source_schema!=1||r.mode!=ActionTimeMode::motion||r.remaining_meaning!=ActionRemainingMeaning::service_estimate||r.shared_gate_kind||!r.retained_wait_phases.empty())fail("MovementActionRegistrationMismatch");}
const TravelExertionBasis& opening(const MovementExactState& s,const StableId& action){const TravelExertionBasis* found=nullptr;for(const auto& row:s.units.rows()){const auto* execution=std::get_if<PersonalMovementExecution>(&row.second.execution);if(!execution||execution->action_id!=action||execution->segment_ordinal!=0||row.second.ordinal!=0)continue;if(row.second.effort_basis_refs.empty())fail("MovementOpeningSourceRequired",action);const auto* basis=s.exertion_bases.find(row.second.effort_basis_refs.front().id);if(!basis||!basis->original_action||basis->original_action->id!=action||basis->original_action->kind!="travel"||basis->original_action->actor_id.empty()||basis->original_action->start_tick!=basis->opened_at.half_day_tick)fail("MovementOpeningActionMismatch",action);if(found)fail("DuplicateMovementOpening",action);found=basis;}if(!found)fail("MovementOpeningSourceRequired",action);return *found;}
const MovementPrefixState& latest_prefix(const MovementExactState& s,const StableId& action){const MovementPrefixState* found=nullptr;Integer ordinal=-1;for(const auto& row:s.prefixes.rows()){const auto* p=std::get_if<PersonalMovementExecution>(&row.second.execution);if(!p||p->action_id!=action)continue;if(p->segment_ordinal==ordinal)fail("DuplicateMovementActionPrefix",action);if(p->segment_ordinal>ordinal){found=&row.second;ordinal=p->segment_ordinal;}}if(!found)fail("MovementActionPrefixRequired",action);return *found;}
const PersonalMovementTerminalSource* terminal(const MovementExactState& s,const StableId& action){const PersonalMovementTerminalSource* result=nullptr;for(const auto& row:s.personal_terminals.rows())if(row.second.actual_action.id==action){if(result)fail("DuplicateMovementActionTerminal",action);result=&row.second;}return result;}
void check_terminal(const CommonRead& common,const MovementExactState& s,const PersonalMovementTerminalSource& result,ExactArithmeticBudget b){const auto& begin=opening(s,result.actual_action.id);const auto* prefix=s.prefixes.find(result.prefix_id);const auto* close=prefix?s.unit_closes.find(prefix->unit_ref+":close"):nullptr;const auto* closed=prefix?std::get_if<MovementClosed>(&prefix->lifecycle):nullptr;if(result.id.empty()||!prefix||!close||!closed||execution_action(prefix->execution)!=result.actual_action.id||!same_source(result.opening_source,{"travel","travel_exertion_basis",begin.id})||!same_source(result.actual_close_source,close->actual_cause)||!same_source(closed->original_result_ref,close->actual_cause)||!same_moment(result.occurred_at,close->occurred_at,b)||take(compare_world_moments(result.occurred_at,begin.opened_at,b))<0||result.actual_action.kind!="travel"||result.actual_action.actor_id!=begin.original_action->actor_id||result.actual_action.start_tick!=begin.original_action->start_tick||common.action(result.actual_action.id))fail("MovementActionTerminalMismatch",result.id);if(result.kind==PersonalMovementTerminalKind::arrived){if(close->kind==MovementCloseKind::arrival)take(read_verified_movement_arrival(s,result.actual_close_source,1,b));else if(close->kind==MovementCloseKind::contact){const MovementArrivalSource* arrival=nullptr;for(const auto& row:s.arrivals.rows())if(row.second.unit_ref==close->unit_ref){if(arrival)fail("DuplicateContactArrival",result.id);arrival=&row.second;take(read_verified_movement_arrival(s,{"travel","movement_arrival",row.first},1,b));}if(!arrival)fail("MovementTerminalArrivalRequired",result.id);}else fail("MovementTerminalArrivalRequired",result.id);}else if(result.kind==PersonalMovementTerminalKind::cancelled){if(close->kind!=MovementCloseKind::cancelled)fail("MovementTerminalCancellationRequired",result.id);}else fail("UnknownMovementTerminalKind",result.id);for(const auto& id:result.actual_action.participants){const auto* actor=common.actor(id);if(actor&&actor->action_id==result.actual_action.id)fail("MovementTerminalParticipantStillOccupied",id);}if(const auto* store=dynamic_cast<const CommonStore*>(&common)){const auto* fact=store->state().facts.find(result.id);if(!fact||fact->domain!="travel"||fact->kind!="personal_movement_terminal")fail("MovementActionTerminalHeadRequired",result.id);}}
void same_proof(const ActionTimeOwnerProof& supplied,const ActionTimeOwnerProof& actual){if(supplied.action_ref!=actual.action_ref||supplied.action_kind!=actual.action_kind||supplied.actor_id!=actual.actor_id||supplied.participant_actor_ids!=actual.participant_actor_ids||supplied.phase!=actual.phase||!same_source(supplied.original_execution_source,actual.original_execution_source)||supplied.source_schema!=actual.source_schema)fail("StaleMovementActionOwner",supplied.action_ref);}
}
ActionTimeRegistration movement_action_time_registration(Integer selected_travel_version){return {"travel","travel","travel",selected_travel_version,1,ActionTimeMode::motion,ActionRemainingMeaning::service_estimate,{},{}};}
Status NativeMovementActionTimeRead::enumerate_action_time_owners(const ActionTimeRegistration& r,ActionTimeOwnerIdSink& output)const{return status([&]{
 registration(r);
 struct BorrowedAction {std::string_view id;const StableId* original;};
 CheckpointVector<BorrowedAction> identities;
 identities.reserve(movement_.exertion_bases.rows().size());
 for(const auto& row:movement_.exertion_bases.rows())if(const auto* p=std::get_if<PersonalMovementExecution>(&row.second.execution)){
  if(!row.second.original_action||row.second.original_action->id!=p->action_id)fail("MovementActionIdentityRequired",row.first);
  identities.push_back({p->action_id,&p->action_id});
 }
 std::sort(identities.begin(),identities.end(),[](const auto& a,const auto& z){return a.id<z.id;});
 const auto end=std::unique(identities.begin(),identities.end(),[](const auto& a,const auto& z){return a.id==z.id;});
 for(auto at=identities.begin();at!=end;++at){take(read_action_time_owner(r,*at->original));take(output.append(at->id));}
});}
Outcome<ActionTimeOwnerProof> NativeMovementActionTimeRead::read_action_time_owner(const ActionTimeRegistration& r,const StableId& action)const{return guard<ActionTimeOwnerProof>([&]{registration(r);const auto& begin=opening(movement_,action);const auto& prefix=latest_prefix(movement_,action);const auto* unit=movement_.units.find(prefix.unit_ref);const auto* latest=unit&&!unit->effort_basis_refs.empty()?movement_.exertion_bases.find(unit->effort_basis_refs.back().id):nullptr;if(!latest||!latest->original_action)fail("MovementActionIdentityRequired",action);const auto* ended=terminal(movement_,action);const auto& identity=ended?ended->actual_action:*latest->original_action;CheckpointVector<std::string_view> members,empty;members.reserve(identity.participants.size());for(const auto& member:identity.participants)members.push_back(member);const auto original_source=SourceRefBuildView{"travel","travel_exertion_basis",begin.id};ActionTimeOwnerProofBuildView out{action,"travel",identity.actor_id,{members},original_source,1,MomentOwnerSourceBuildView{original_source,1},ActionTimeOwnerPhase::working,{},{},{},{empty},{}};if(ended){check_terminal(common_,movement_,*ended,budget_);out.phase=ActionTimeOwnerPhase::terminal;out.ended_source=MomentOwnerSourceBuildView{{"travel","personal_movement_terminal",ended->id},1};out.terminal_result_ref=ended->id;return ActionTimeOwnerProof(out);}const auto* actual=common_.action(action);if(!actual||actual->kind!="travel"||actual->actor_id!=identity.actor_id||actual->participants!=identity.participants||actual->start_tick!=begin.opened_at.half_day_tick||(!travel_.actions.find(action)&&!travel_.road_actions.find(action)))fail("MovementOriginalActionMissing",action);out.phase=std::holds_alternative<MovementActive>(prefix.lifecycle)?ActionTimeOwnerPhase::working:ActionTimeOwnerPhase::suspended;return ActionTimeOwnerProof(out);});}
Outcome<OriginalPersonalMovementDestination> NativeMovementActionTimeRead::read_original_execution_destination(const StableId& action_id)const{return guard<OriginalPersonalMovementDestination>([&]{
 const auto owner=take(read_action_time_owner(movement_action_time_registration(),action_id));const auto& begin=opening(movement_,action_id);const SourceRef source{"travel","travel_exertion_basis",begin.id};
 const auto at=take(read_movement_source_moment(movement_,source,1,budget_));if(!same_source(owner.original_execution_source,source)||!same_moment(at,begin.opened_at,budget_))fail("MovementOpeningDestinationSourceMismatch",action_id);
 OriginalPersonalMovementDestination out;out.action_id=action_id;out.actor_id=owner.actor_id;out.execution_source={source,1};out.started_at=at;
 if(const auto* road=std::get_if<RoadMovementBasis>(&begin.actual_basis)){
  const auto& motion=road->original_inputs;const auto& p=motion.params;const auto* edge=catalog_.roads.find(motion.edge_id);
  if(!edge||motion.actor_id!=owner.actor_id||motion.action_id!=action_id||motion.origin!=edge->origin||p.edge_index<0||p.edge_index>=static_cast<Integer>(p.path.size())||p.path[static_cast<std::size_t>(p.edge_index)]!=edge->id)fail("MovementOriginalRoadDestinationRequired",action_id);
  StableId reached=p.returning?edge->origin:edge->destination;
  // 原finish_road_leg的有限路径方向；不以旧命令destination键替代已采用path。
  if(!(p.returning&&!p.reverse_first))for(std::size_t i=static_cast<std::size_t>(p.edge_index)+1;i<p.path.size();++i){const auto* next=catalog_.roads.find(p.path[i]);if(!next||next->origin!=reached)fail("MovementOriginalRoadPathDisconnected",action_id);reached=next->destination;}
  const auto* town=catalog_.settlements.find(reached);if(!town||town->entry_place.empty())fail("MovementOriginalRoadDestinationRequired",action_id);out.destination=reached;out.actual_destination_anchor=OriginalMovementAnchor{SettlementLocation{reached,town->entry_place},source};
 }else{
  const auto& p=std::get<TerrainCostBasis>(begin.actual_basis).original_inputs;const auto* plan=travel_.journey_facts.find(p.plan_id);
  if(!plan||plan->id!=p.plan_id||plan->actor_id!=owner.actor_id||plan->action_id!=action_id||plan->map_id!=p.map_id||plan->mode!=p.mode||plan->budget!=p.budget||!original_destination_equal(plan->destination,p.destination)||plan->points.size()<2||!destination_point_equal(plan->origin,plan->points.front())||p.route_index<1||p.route_index>=static_cast<Integer>(plan->points.size())||!catalog_.maps.find(p.map_id))fail("MovementOriginalTerrainDestinationRequired",action_id);
  const auto suffix=plan->points.begin()+static_cast<std::size_t>(p.route_index);if(p.points.size()!=static_cast<std::size_t>(plan->points.end()-suffix)||!std::equal(p.points.begin(),p.points.end(),suffix,destination_point_equal))fail("MovementOriginalTerrainPathMismatch",action_id);
  if(const auto* store=dynamic_cast<const CommonStore*>(&common_)){const auto* head=store->state().facts.find(plan->id);if(!head||head->domain!="travel"||head->kind!="terrain_journey")fail("MovementOriginalTerrainPlanHeadRequired",plan->id);}
  out.destination=p.destination;if(const auto* town_id=std::get_if<StableId>(&p.destination)){const auto* town=catalog_.settlements.find(*town_id);if(!town||!destination_point_equal(town->map_xy,plan->points.back())||town->entry_place.empty())fail("MovementOriginalTerrainDestinationRequired",action_id);out.actual_destination_anchor=OriginalMovementAnchor{SettlementLocation{*town_id,town->entry_place},source};}else{const auto point=std::get<PointI>(p.destination);if(!destination_point_equal(point,plan->points.back()))fail("MovementOriginalTerrainDestinationRequired",action_id);out.actual_destination_anchor=OriginalMovementAnchor{WildernessLocation{p.map_id,p.origin,point},source};}
 }
 return out;
});}
Outcome<std::optional<MomentOwnerSource>> NativeMovementActionTimeRead::read_original_execution_funding_plan(const StableId& action_id)const{return guard<std::optional<MomentOwnerSource>>([&]{
 const auto actual=take(read_original_execution_destination(action_id));const auto& basis=opening(movement_,action_id);if(!basis.accepted_funding_plan)return std::optional<MomentOwnerSource>{};
 const auto& accepted=*basis.accepted_funding_plan;if(accepted.source_schema!=1||accepted.source_ref.domain!="tasks"||accepted.source_ref.kind!="task_carrier_agreement_accepted"||accepted.source_ref.id.empty())fail("PersonalFundingAcceptedTaskSourceRequired",action_id);
 const auto* store=dynamic_cast<const CommonStore*>(&common_);if(!store)fail("MovementActualCommonOrderRequired",action_id);
 const auto& facts=store->state().facts;const auto* head=facts.find(accepted.source_ref.id);const auto* opening_head=facts.find(actual.execution_source.source_ref.id);
 if(!head||head->domain!=accepted.source_ref.domain||head->kind!=accepted.source_ref.kind||!opening_head||opening_head->domain!="travel"||opening_head->kind!="travel_exertion_basis")fail("PersonalFundingAcceptedTaskSourceRequired",action_id);
 const auto& order=facts.order();const auto before=std::find(order.begin(),order.end(),accepted.source_ref.id),after=std::find(order.begin(),order.end(),actual.execution_source.source_ref.id);
 if(before==order.end()||after==order.end()||before>=after)fail("PersonalFundingNotAcceptedAtDeparture",action_id);
 return basis.accepted_funding_plan;
});}
Status NativeMovementActionTimeRead::validate_original_execution_common_order(const StableId& action_id,const SourceRef& accepted,const SourceRef& dispatch)const{return status([&]{
 const auto actual=take(read_original_execution_destination(action_id));const auto* store=dynamic_cast<const CommonStore*>(&common_);if(!store)fail("MovementActualCommonOrderRequired",action_id);
 const SourceRef refs[]={accepted,actual.execution_source.source_ref,dispatch};std::size_t positions[3]={};
 for(std::size_t n=0;n<3;++n){if(!source_valid(refs[n]))fail("MovementActualCommonSourceRequired",action_id);const auto* head=store->state().facts.find(refs[n].id);if(!head||head->domain!=refs[n].domain||head->kind!=refs[n].kind)fail("MovementActualCommonSourceRequired",refs[n].id);const auto& order=store->state().facts.order();const auto at=std::find(order.begin(),order.end(),refs[n].id);if(at==order.end())fail("MovementActualCommonOrderRequired",refs[n].id);positions[n]=static_cast<std::size_t>(at-order.begin());}
 if(!(positions[0]<positions[1]&&positions[1]<positions[2]))fail("MovementAcceptanceExecutionDispatchOrderMismatch",action_id);
});}
Outcome<WorldMoment> NativeMovementActionTimeRead::read_action_time_source(const ElapsedTimeSource& source)const{return guard<WorldMoment>([&]{const auto* exact=std::get_if<MomentOwnerSource>(&source);if(!exact||exact->source_schema!=1||exact->source_ref.domain!="travel")fail("MovementExactTimeSourceRequired");if(exact->source_ref.kind=="personal_movement_terminal"){const auto* end=movement_.personal_terminals.find(exact->source_ref.id);if(!end)fail("MovementActionTerminalRequired",exact->source_ref.id);check_terminal(common_,movement_,*end,budget_);return end->occurred_at;}return take(read_movement_source_moment(movement_,exact->source_ref,1,budget_));});}
Status NativeMovementActionTimeRead::validate_fixed_action_sources(const ActionTimeRegistration&,const ActionTimeOwnerProof&,const ActionElapsedState&,const std::vector<FixedServiceTransition>&)const{return common_failure("MovementDoesNotOwnFixedClock");}
Status NativeMovementActionTimeRead::validate_shared_action_sources(const ActionTimeRegistration&,const ActionTimeOwnerProof&,const SharedWorkElapsedState&)const{return common_failure("MovementDoesNotOwnSharedWorkGate");}
Outcome<RunStop> NativeMovementActionTimeRead::read_action_continuation_stop(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment& current)const{return guard<RunStop>([&]{auto proof=take(read_action_time_owner(r,supplied.action_ref));same_proof(supplied,proof);const auto& p=latest_prefix(movement_,proof.action_ref);if(take(compare_world_moments(p.last_settled_at,current,budget_))>0)fail("MovementSourceInFuture",p.id);if(const auto* end=terminal(movement_,proof.action_ref))return end->kind==PersonalMovementTerminalKind::arrived?RunStop::arrived:RunStop::cancelled;return take(read_movement_continuation_stop(movement_,p.id,budget_));});}
Outcome<OriginalActionRemaining> NativeMovementActionTimeRead::read_original_action_remaining(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment& current)const{return guard<OriginalActionRemaining>([&]()->OriginalActionRemaining{auto proof=take(read_action_time_owner(r,supplied.action_ref));same_proof(supplied,proof);const auto& p=latest_prefix(movement_,proof.action_ref);if(take(compare_world_moments(p.last_settled_at,current,budget_))>0)fail("MovementSourceInFuture",p.id);if(const auto* end=terminal(movement_,proof.action_ref))return ActualServiceRemaining{ActualServiceRemainingBuildView{HalfDayDuration{},{"travel","personal_movement_terminal",end->id},1}};auto remaining=take(read_movement_conditional_remaining(movement_,catalog_,services_,p.id,budget_));return ActualServiceRemaining{ActualServiceRemainingBuildView{remaining.conditional_remaining,{remaining.actual_basis_source.domain,remaining.actual_basis_source.kind,remaining.actual_basis_source.id},1}};});}
Outcome<StableId> NativeMovementActionTimeRead::read_gate_result_id(const SharedWorkGateResult&)const{return {false,{},common_failure("MovementDoesNotOwnSharedWorkGate").error};}
Outcome<SharedWorkGateResult> NativeMovementActionTimeRead::read_original_gate_result(const StableId&)const{return {false,{},common_failure("MovementDoesNotOwnSharedWorkGate").error};}
